import{_ as t,o as r,c as a,ai as s}from"./chunks/framework.C33Uq6m-.js";const h=JSON.parse('{"title":"Référence développeur","description":"","frontmatter":{},"headers":[],"relativePath":"fr/reference/index.md","filePath":"fr/reference/index.md"}'),o={name:"fr/reference/index.md"};function i(d,e,n,l,c,u){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="reference-developpeur" tabindex="-1">Référence développeur <a class="header-anchor" href="#reference-developpeur" aria-label="Permalink to &quot;Référence développeur&quot;">​</a></h1><p>Cette section fournit la documentation technique pour les développeurs souhaitant comprendre, modifier ou contribuer à LLMxRay.</p><h2 id="vue-d-ensemble" tabindex="-1">Vue d&#39;ensemble <a class="header-anchor" href="#vue-d-ensemble" aria-label="Permalink to &quot;Vue d&#39;ensemble&quot;">​</a></h2><p>LLMxRay est une application monopage (SPA) Vue 3 + TypeScript qui communique avec une instance locale d&#39;Ollama. Elle utilise Pinia pour la gestion d&#39;état, IndexedDB pour la persistance, et une architecture en streaming pour l&#39;affichage des tokens en temps réel.</p><table tabindex="0"><thead><tr><th>Couche</th><th>Technologie</th></tr></thead><tbody><tr><td>Framework</td><td>Vue 3.5 + Composition API (<code>&lt;script setup&gt;</code>)</td></tr><tr><td>Langage</td><td>TypeScript 5.9 (strict)</td></tr><tr><td>Build</td><td>Vite 7.3</td></tr><tr><td>Styles</td><td>Tailwind CSS 4.2</td></tr><tr><td>État</td><td>Pinia 3 (un store par domaine)</td></tr><tr><td>Routage</td><td>Vue Router 5</td></tr><tr><td>Graphiques</td><td>Chart.js 4 + vue-chartjs, D3.js 7</td></tr><tr><td>Canvas</td><td>Vue Flow 1.x (éditeur visuel à base de nœuds)</td></tr><tr><td>Éditeur de code</td><td>CodeMirror 6</td></tr><tr><td>Parseur AST</td><td>Recast + @babel/parser</td></tr><tr><td>Stockage</td><td>IndexedDB (natif du navigateur)</td></tr><tr><td>Backend LLM</td><td>Ollama (local, via proxy)</td></tr></tbody></table><h2 id="sections" tabindex="-1">Sections <a class="header-anchor" href="#sections" aria-label="Permalink to &quot;Sections&quot;">​</a></h2><ul><li><strong><a href="./architecture.html">Architecture</a></strong> — Flux de données, streaming, stockage, plugins</li><li><strong><a href="./stores.html">Stores</a></strong> — Les 24 stores Pinia avec leur état et leurs actions</li><li><strong><a href="./services.html">Services</a></strong> — Les 36 modules de services avec leurs responsabilités</li><li><strong><a href="./composables.html">Composables</a></strong> — Les 7 composables Vue</li><li><strong><a href="./types.html">Types</a></strong> — Interfaces TypeScript principales</li><li><strong><a href="./api-integration.html">Intégration API</a></strong> — Endpoints Ollama, proxy, protocoles de streaming</li><li><strong><a href="./testing.html">Tests</a></strong> — Configuration et pratiques Vitest et Playwright</li></ul>',7)])])}const m=t(o,[["render",i]]);export{h as __pageData,m as default};
